import collections
import sys

def min_steps(lst):
    dp = {}
    res = collections.defaultdict(int)

    def go(n, div=3):
        if n in dp:
            return dp[n]
        if n < 0 or (n % div == 0 and n != 0):
            return res[n] = float('inf')
        for k in range(1, min(len(lst), n+1)):
            go(n - lst[k], div)
            dp[n] = min(dp[n], dp[n-k] + 1)
        res[n] = dp[n]
        return dp[n]

    go(lst[0])
    for test_case in sys.stdin:
        n = int(test_case)
        moves = min_steps([1, -1])
        if moves[-1] <= 10:
            print("First")
        else:
            print("Second")
```

