def distance(x1, y1, x2, y2):
    return abs(x1 - x2) + abs(y1 - y2)

def solve(n, a):
    if n == 1:
        max_val = max(a)
        return max_val * 2

    graph = {}
    for i in range(n):
        x = a[i * 2]
        y = a[i * 2 + 1]
        if x not in graph:
            graph[x] = []
        graph[x].append((y, i+1))

    def find_min_path(x, visited=None):
        if visited is None:
            visited = set()

        min_distance = float('inf')
        min_index = None

        for neighbor, index in graph[x]:
            if index not in visited:
                visited.add(index)
                distance_to_neighbor = distance(x, a[index*2], x, a[index*2+1])
                new_distance = min_distance + distance_to_neighbor
                if new_distance < min_distance:
                    min_index = index
                    min_distance = new_distance

        return min_index, min_distance

    shortest_path = None
    shortest_distance = float('inf')
    for start in graph.keys():
        path, distance = find_min_path(start)
        if distance < shortest_distance:
            shortest_path = path
            shortest_distance = distance

    path_coords = []
    current = shortest_path

    while current is not None:
        x, y = a[current*2], a[current*2+1]
        path_coords.append((x, y))
        current = graph[x].pop(0)[1]

    path_length = sum(distance((path_coords[i][0], path_coords[i][1]), path_coords[i+1][0], path_coords[i+1][1]) for i in range(len(path_coords)-1)) + distance(path_coords[-1][0], path_coords[-1][1], path_coords[0][0], path_coords[0][1])
    return shortest_distance, *path_coords
