import math
import itertools
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def is_prime(n):
    if n <= 1 or (n % 2 == 0 and n > 2):
        return False
    root = int(math.sqrt(n)) + 1
    for i in range(3, root, 2):
        if n % i == 0:
            return False
    return True

def solve(points):
    a, b = [p >> 1 for p in points], [p & 1 for p in points]
    lcm_ab = reduce(lcm, a + ([1] if abs(sum(a) - sum(b)) else []), 1)
    primes = [p for p in range(2, int(lcm_ab ** 0.5) + 1) if is_prime(p)]
    max_len = len(set(itertools.chain(*[itertools.repeat(p, q) for p, q in zip(a, b)]))) - len(points) + 2
    possible_lengths = [lcm * p for lcm in primes]
    closest = min((k, v) for k, v in enumerate(possible_lengths))[0]
    factors = [(p**ex, -p**(-ex)) for ex, p in zip(closest//2 + [1], primes[closest]) if p < max(a)]
    factors = sorted(factors, key=lambda item: item[0], reverse=True)
    x_y_list = []
    ct = 0
    for (m, n), a_i in zip(factors, points):
        while a_i % m != 0 and len(x_y_list) < len(points):
            ct += m
            x_y_list.append((ct, (a_i - ct) * n))
            if len(x_y_list) >= len(points):
                break
        if len(x_y_list) == len(points):
            break
    return sorted(x_y_list), sum((p1-p2)[0] + (q1-q2)[0] for p1, q1, p2, q2 in zip(x_y_list[:2], x_y_list[2:]))
