from heapq import heappush, heappop

def solve(x_chest, y_key, k):
    # Define the maximum number of steps that can be taken.
    max_steps = x_chest + k

    # Define a priority queue to store the (distance, current position) pairs.
   # The distance is the smallest time required to reach the current position from 0.
    # The first element in the pair represents the current position and the second one represents the time spent so far.
    q = [(0, 0)]
    dist = {0: 0}

    while q:
        curr_pos, time_spent = heappop(q)

        # If the current position is the key or the chest, return the smallest time spent so far.
        if curr_pos == x_chest:
            if y_key in dist and dist[y_key] <= time_spent + k:
                # Check if there's enough stamina to open the chest after picking up the key.
                if abs(x_chest - y_key) <= k or (abs(x_chest - y_key) == k and not (x_chest > curr_pos and y_key < curr_pos)):
                    return time_spent + dist[y_key]
        elif curr_pos == y_key:
            if x_chest in dist and dist[x_chest] <= time_spent + k:
                # Check if there's enough stamina to open the chest after carrying it.
                if abs(x_chest - y_key) <= k or (abs(x_chest - y_key) == k and not (x_chest > curr_pos and y_key < curr_pos)):
                    return time_spent + dist[x_chest] + abs(x_chest - y_key)

        # Update the distance to the current position and the neighboring positions.
        for delta in (-1, 1):
            next_pos = curr_pos + delta
            time_for_step = delta + time_spent

            if next_pos >= 0 and max_steps >= next_pos:
                if next_pos not in dist or (dist[next_pos] > time_for_step):
                    dist[next_pos] = time_for_step
                    heappush(q, (next_pos, time_for_step))

def main():
    for _ in range(int(input())):
        x_chest, y_key, k = map(int, input().split())
        print(solve(x_chest, y_key, k))

# Run the main function
