    primes = []
    prime_bits = bytearray((limit // 2) + 2, True)

    for i in range(2, int(math.sqrt(limit)) + 1):
        if prime_bits[i]:
            j = (i*i) << 1
            while j < len(prime_bits):
                prime_bits[j] = False
                j += i + (i % i) * (2*i)
    primes.append(2)

    for i in range(3, len(prime_bits), 2):
        if prime_bits[i]:
            primes.append(i)

    return primes

def triple(n):
    r = (n * n + n) // 2
    return int((math.sqrt(8*r + 0.25)-math.sqrt(8*r-0.25))/2)

def bi_divisible(a, b):
    return a % b == 0 or a - b in [1, -1]
