import math
import itertools

def solve(n):
    def prime_factors(num):
        factors = []
        i = 2
        while i * i <= num:
            if num % i == 0:
                factors.append(i)
                num //= i
            else:
                i += 1
        if num > 1:
            factors.append(num)
        return factors[::-1]

    def gcd(a, b):
        while b != 0:
            a, b = b, a % b
        return a

    limit = int(math.cbrt(n * 3)) + 1
    primes = set([p for p in range(2, limit) if len(prime_factors(p)) == 1])

    def candidate(p1):
        if (p1 * 3 // n) not in primes:
            return False
        p2 = next((primes - {p1}), 0) if p1 != limit - 1 else 0
        if p2 and (gcd(p1 * 3, p2) != 1):
            return False
        return True

    a = []
    max_candidate = 0
    for p in primes:
        if candidate(p):
            max_candidate = p
            break

    a.append(max_candidate)
    a.extend([max_candidate * 3, max_candidate * 3])
    step = max(max_candidate * 3 // n, 1)

    for i in range(2, n - 1):
        a.append((a[-1] + step) if (i + 1 != n and candidate(a[-1] + step)) else (a[-1] + step) + 1)
        step += max_candidate * 3 // a[-1]

    return a

