import sys
from collections import defaultdict

def solve():
    t = int(sys.stdin.readline())

    for _ in range(t):
        n = int(sys.stdin.readline())
        a = list(map(int, sys.stdin.readline().split()))

        graph = defaultdict(list)
        odd = [i for i in a if i % 2]
        even = [i for i in a if i % 2 == 0]

        for i, num in enumerate(a):
            for j in map(abs, a[max(i+1, n)::-1] + a[:min(i, n)]):
                graph[num].append((j, i))

        odd.sort()
        even.sort()

        visited = set()

        def dfs(node, parity):
            if node in visited:
                return False

            nonlocal odd, even

            visited.add(node)
            for neibour, ind in graph[node]:
                cur_parity = not parity
                if (cur_parity and neibour in visited) or \
                   (not cur_parity and neibour in odd and neibour not in visited):
                    return False

                if dfs(neibour, cur_parity):
                    return True

            return False

        if not dfs(odd[0], True):
            print("NO")
            continue

        odd.clear()
        visited.clear()
        for i in range(n):
            if a[i] % 2:
                odd.append(a[i])
            else:
                a[i] = 0

        colored = ['.' for _ in range(n)]
        ind = (colored.index(min(colored))+1)%2
        node = even[ind]
        colored[node] = str(ind+1).replace("0", '_')

        for i, num in enumerate(a):
