def solve(arr):
    n = len(arr)
    parents = list(range(n))
    rank = [1] * n
    coloring = defaultdict(int)
    parity = 0

    def find(i):
        if parents[i] != i:
            parents[i] = find(parents[i])
        return parents[i]

    def union(x, y):
        x_rep = find(x)
        y_rep = find(y)

        if x_rep == y_rep:
            return False

        if rank[x_rep] < rank[y_rep]:
            parents[x_rep] = y_rep
            rank[y_rep] += rank[x_rep]
