def solve(arr):
    n = len(arr)
    if n < 2:
        return 0

    max_heap, min_heap = [], []
    heapq.heappush(max_heap, (-arr[0], 0))
    heapq.heappush(min_heap, (arr[-1], -1))

    for i in range(1, n):
        if not max_heap or -max_heap[0][0] > arr[i]:
            heapq.heappush(max_heap, (-arr[i], i))
        if not min_heap or min_heap[-1][0] < arr[n-i-1]:
            heapq.heappush(min_heap, (arr[n-i-1], n-i-1))

    operations = 0
    while max_heap and min_heap:
        max_elem, max_ix = -max_heap.pop()[1], -max_heap[0][1]
        min_elem, min_ix = min_heap[-1][0], min_heap[-1][1]
        if not max_ix < min_ix:
            operations += max_ix - min_ix + 1
            for i in range(min_ix+1, max_ix):
                arr[i-1] += 1
                arr[i] -= 1
        else:
            min_heap.pop()
    return operations
