import itertools

def solve(grid):
    rows = [list(row) for row in grid]
    words = [''.join(cols) for cols in zip(*rows)]

    # Find all possible ordered combinations of substrings in the grid
    candidates = set()
    for i in range(1, len(words)):
        combos = itertools.combinations(words, r=i)
        candidates.update({''.join(combo) for combo in combos})

    # Filter out improper combinations (e.g., "hello" should not be a candidate if "l" is found independently)
    filtered_candidates = set()
    for word in candidates:
        for char in word:
            if char not in rows and char not in '{0.}'.format(word):
                break
        else:
            filtered_candidates.add(word)

    # Search the remaining candidates in grid (row-wise and column-wise, in decreasing order of length)
    def search(candidate, pos=None):
        if not candidate:
            return True

        for i, row in enumerate(rows):
            if i == 8:  # If the complete word is found, return True
                if candidate[0] == '.':
                    continue
                if candidate[0] == row[pos]:
                    return search(candidate[1:], pos)

            for j, cell in enumerate(row):
                if cell == '.':
                    if candidate[len(candidate)-1] == '.' and (len(candidate) == 2 or pos is not None):
                        # The period at the end can only match an empty cell on a valid position, or can be matching itself in case of 2-letter words
                        if search(candidate[0:len(candidate)-1], pos=j):
                            return True
                    elif candidate[0] == cell and search(candidate[1:], j):
                        return True

        return False

    for candidate in sorted([w for w in filtered_candidates if len(w) > 1], key=len, reverse=True):
        if search(candidate):
            return candidate.lower()
    return None
