from collections import defaultdict, Counter
import sys

def solve(n, a):
    diff_count = defaultdict(int)
    pairs = [(a[i], a[j]) for i in range(n-1) for j in range(i+1, n)]
    for pair in pairs:
        diff_count[abs(pair)] += 1

    freq = Counter(diff_count.keys())
    initial_diffs = [1] + list(diff_count.keys()) + [n-1]

    # find the count of odd frequency differences
    odd_freq = sum(1 for x in diff_count if freq[x] % 2 != 0)

    # any odd frequency difference means at least one pair has a unique difference to initial numbers, so there must be
    # a solution with the difference in this pair being the only occurance of that difference
    if odd_freq > 1:
        return None

    # If total number of different differences is even and odd\_freq == 0, then initial difference can be any diff value
    if (n-2) // 2 + bool(odd_freq == 0) > 0:
        return None

    # Find the unique difference with odd frequency to select an initial pair
    for x in initial_diffs:
        if freq[x] % 2 != 0:
            # find pair that has this particular difference
            for i in range(n-1):
                for j in range(i+1, n):
                    if a[j] - a[i] == x:
                        return min(a[i], a[j])

    # If there is no such pair, return the median of the list.
    a.sort()
    return a[(n-1) // 2]

