from collections import defaultdict

def solve(s):
    colors = set(s)
    if len(colors) == 1:
        return -1

    bulbs = list(range(len(s)))
    states = [0] * len(bulbs)
    dfs_visited = set()
    color_stack = []

    def dfs(idx, color):
        if idx == len(bulbs):
            return True

        for i in range(len(bulbs)):
            current_color = s[i]
            if (states[i] == 0 and current_color != color) or (states[i] == 1 and current_color in dfs_visited):
                continue

            states[i] ^= 1
            dfs_visited.add(current_color)
            color_stack.append(current_color)

            if dfs(idx + 1, color):
                return True

            states[i] ^= 1
            dfs_visited.remove(color_stack.pop())

    for c in colors:
        if dfs(0, c):
            return len(s) - sum(states)

    return -1

