def solution(target_position):
    grid = [[False for _ in range(-100, 101)] for __ in range(-100, 101)]
    grid[0][0] = True

    queue = collections.deque([(0, 0)])
    previous_moves = {(0, 0): []}

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        current_position = queue.popleft()
        if current_position == target_position:
            break

        for direction in directions:
            next_position = (current_position[0] + direction[0], current_position[1] + direction[1])
            if validate_position(next_position) and not grid[next_position[0]][next_position[1]]:
                grid[next_position[0]][next_position[1]] = True
                queue.append(next_position)
                previous_moves[next_position] = previous_moves[current_position] + [direction] if current_position in previous_moves else [direction]

    path_length = manhattan_distance(target_position, (0, 0))

    legal_paths = []

    def is_legal(path):
        for i, move in enumerate(path[1:]):
            if (path[i + 1] == move or path[i+1][0] - path[i+2][0] != -1 and path[i+1][0] - path[i+2][0] != 1) \
