                return False
            if not validate_position((path[i+2][0] + move[0], path[i+2][1] + move[1])):
                return False
        return True

    for path in itertools.permutations([(0, 1), (0, -1), (1, 0), (-1, 0)] * path_length):
        if is_legal(path):
            legal_paths.append(list(path))

    min_path = None
    for path in legal_paths:
        if not min_path or manhattan_distance(target_position, (0, 0)) <= sum(abs(_[0]) + abs(_[1]) for _ in path):
            min_path = path

    return min([manhattan_distance((0, 0), p) + len(p) for p in legal_paths if manhattan_distance((0, 0), p) + len(p) == manhattan_distance((0, 0), min_path)])

