import sys
from itertools import combinations

def solve(n, s, r):
    if n == 2:
        diff = s - r
        return [1 + diff // (s - r), r] if 0 < diff <= s - r else [s - diff, r]

    solutions = []

    for k in range(r + 1, s):
        for subset in combinations(range(1, k+1), n-1):
            if sum(subset) + k == s and (k - max(subset)) <= r:
                solutions.append((list(subset) + [k],))

    if not solutions:
        return solve(n - 1, r, s)

    cache = {}

    def backtrack(remaining_dice, remaining_sum):
        k = remaining_sum - remaining_dice

        if k in cache:
            return cache[k]

        if not remaining_dice:
            return []

        for i, (val,) in enumerate(solutions):
            if val <= remaining_sum and (i + 1) <= remaining_dice:
                rest = backtrack(remaining_dice - (i+1), remaining_sum - val)
                seq = solutions[(i+1):] + [(val,)] + rest

                if not rest or len(rest) + 1 <= max(seq) - min(seq):
                    if not cache[remaining_sum]:
                        cache[remaining_sum] = seq
                    else:
                        cache[remaining_sum].extend(seq)

    backtrack(n, s)

    return sorted(cache[s])

for _ in range(int(sys.stdin.readline().strip())):
    n, s, r = map(int, sys.stdin.readline().split())
    print(*solve(n, s, r))
