from collections import deque
import sys

def solve(n):
    # Initialize the deck with a single white card and an empty black stack
    deck = deque([1]) + deq
    deq = deque()

    # Alternate colors as per the rule
    color = 1

    # Step through each deal operation
    for _ in range(n):
        # Add cards to the respective queue based on their color
        if color == 1:
            deck.appendleft(color)
            deq.extend(deck[:min(len(deck), 2)])
        else:
            deck.append(color * -1)
            deq.extend(deck[:min(len(deck), 2)])

        # Update the color
        color *= -1

    # Lastly, deal all remaining cards to the current player
    while len(deck):
        if color == 1:
            deq.appendleft(deck.popleft() * color)
        else:
            deq.append(deck.pop() * color)

    # Compute and return the number of cards for each player-color combination
    white_alice, black_alice, white_bob, black_bob = 0, 0, 0, 0
    for card in deq:
