def dijkstra(grid):
    dist = {}
    for i, row in enumerate(grid):
        for j, _ in enumerate(row):
            que = []
            heapq.heappush(que, (0, (i, j)))
            dist[(i, j)] = 0
            visited = set()
            while que:
