from math import factorial as fact
import sys

def solve(k):
    # dp[i]: stores the maximum x such that x! + (x-1)! is a multiple of k for 2 <= x <= i
    dp = [0] * (k // 2 + 1)
    dp[1] = 1

    for i in range(2, len(dp)):
        # for each possible divisor d of i-1!, check if (i-d)-1 and i-d are relatively prime and the remainder when (i-d)-1! is divided by k is 0
        for d in range(2**(i//2), (i - 1) // 2 + 1):
            # gcd(a, b) returns the greatest common divisor of a, b
            if __gcd(d, i - d) == 1 and k % (dp[d] * (i - d)) == 0:
                dp[i] = max(dp[i], (i- d) + 1)
    return dp[-1] if dp[-1] < k else -1

