    slope = float(point[1] - slice[1]) / (point[0] - slice[0]) if point[0] != slice[0] else None
    intercept = slice[1] - slope * slice[0] if slope else None
    return [slice[0], intercept] if not slope else [slice[0], math.inf] if slope > 0 else [slice[0], -math.inf]

def rotate(slice, angle):
    rotation_matrix = [[math.cos(angle), -1 * math.sin(angle)],
                       [math.sin(angle), math.cos(angle)]]
    return list(map(lambda x: sum(y * z for y, z in zip(rotation_matrix, [slice[0], slice[1]])), [slice[0], slice[1]]))

def merge_slices(slices):
    # Merge sorted slices from top to bottom, first by their starting x-coordinate, then by y-coordinate.
    for i in range(len(slices) - 1, 0, -1):
        for j in reversed(range(i)):
            if slices[j][0] > slices[i][0]:
                break
            if slices[j][0] == slices[i][0] and min(slices[j][1], slices[i][1]) > max(slices[j][1], slices[i][1]):
                slices[i], slices[j] = slices[j], slices[i]
    merged_slices = []
    current_end = [0, math.inf]
    for slice in sorted(slices, key=lambda x: (x[0], -x[1])):
        if extend_to_point(current_end, slice) is not None and gcd(current_end[0] - slice[0], current_end[1] - slice[1]) == 1:
            extended = extend_to_point(current_end, slice)
            merged_slices[-1].append((extended[0], max(extended[1], current_end[1]), min(extended[1], current_end[1])))
            current_end = extended
        else:
            merged_slices.append([slice])
            current_end = slice
    return merged_slices

def is_valid(slices):
    for idx, (current_start, current_end) in enumerate(sorted(slices, key=lambda x: x[0][0])):
        # The bottom edge of each cheese should be a segment of the x-axis.
        if min(current_start[1], current_end[1] + 1) > 0: return False

        # No two slices of cheese overlap, but their sides can touch.
        for next_slice in sorted(slices, key=lambda x: x[0][0])[idx+1:]:
            if not (next_slice[0][0] > current_end[0] or current_start[0] > next_slice[0][0]):
                if (min(current_start[1], current_end[1]) >= min(next_slice[0][1], next_slice[1][1]) and
                    max(current_start[1], current_end[1]) <= max(next_slice[0][1], next_slice[1][1])):
                        return False
    # They form one connected shape.
    vertices = set()
    for slice in sorted(slices, key=lambda x: x[0][0]):
        if slice[0][0] not in vertices:
            vertices.add(slice[0][0])
        x_len = (max([point[0] for point in slice[1:]]) - min([point[0] for point in slice[1:]]))
        y_len = (max([point[1] for point in slice[1:]]) - min([point[1] for point in slice[1:]]))
        vertices.update(list(zip(*[[j, k] for j in range(min([point[0] for point in slice[1:]]), min([point[0] for point in slice[1:]] + x_len + 1)) for k in range(min([point[1] for point in slice[1:]], min([point[1] for point in slice[1:]] + y_len)))])))
    if len(vertices) != sum(len(slice) - 1 for slice in slices):
        return False
    # Check no two vertices have the same y-coordinate, since they form a valid polygon.
    return all([(v[0] == w[0]) != (v[1] == w[1]) for v, w in zip(sorted(vertices), sorted(vertICES)) if v and w])

def solve(slices):
    rotated_slices = [rotate(slice, angle) for angle in (0, math.pi/2, -math.pi/2) for slice in slices]
    valid_slices = sorted([slice for slice in rotated_slices if is_valid(slice)], key=lambda x: len(x))
    return valid_slices and min(sum((abs(len(slice) - 2) + len(slice[0][1:]) - 2) for slice in sorted(valid_slices, key=lambda y: y[-1])) * 4, len(rotated_slices))

def main():
    with open('input.txt', 'r') as rfile:
        lines = [line.strip().split(' -> ') for line in rfile.readlines()]
    input_data = [[[int(_) for _ in _] for _ in _] for _ in sorted(list(map(extend, lines)))]
    answer1 = solve([list(chain(*input_data[i])) for i in range(len(input_data)) if len(input_data[i]) > 1])
    answer2 = sorted(solve([list(rotate(list(chain(*input_data[i]))) for j in range(3) for i in range(len(input_data)))])[-1])[-1]
    print('Answer 1:', answer1)
    print('Answer 2:', answer2)

