import math

def solve(N, M):
    grid = list(range(1, (N * M) + 1))
    tight_dominoes = set()

    # Iterate through the grid diagonally to identify tight dominoes
    for i in range(M):
        row_start = (i + 1)
        col_start = (i + 1)
        while row_start <= N and col_start <= M:
            tile_1 = grid[row_start - 1 + (col_start - 1)]
            tile_2 = grid[row_start + col_start - 1]

            # If the difference between tiles is 1, add to the set of tight dominoes
            if abs(tile_1 - tile_2) == 1:
                tight_dominoes.add((tile_1, tile_2))

            row_start += 1
            col_start += 1

    # Remove duplicate domino pairs from the set
    tight_dominoes = list(tight_dominoes)
    for i in range(len(tight_dominoes)):
        for j in range(i + 1, len(tight_dominoes)):
            if tight_dominoes[i] == sorted(tight_dominoes[j]):
                del tight_dominoes[j]

    # Return the number of unique tight dominoes
    return len(tight_dominoes)
