                continue
        else:
            return "\n".join(" ".join(map(str, pair)) for pair in pairs)

    # Let k be even and find a set S of size n/2 such that (a + k) * b is divisible by 4 for all pairs (a,b) where a,b are elements of S

    odd = list(range(1, int(n/2)+1))
    S = []

