from itertools import permutations, combinations

def sorted_indices(arr):
    indices = list(range(len(arr)))
    return sorted(indices, key=lambda i: arr[i])

def next_permutation(perm):
    n = len(perm)
    i = n - 1
    while i > 0 and perm[i - 1] >= perm[i]:
        i -= 1
    if i == 0:
        return False   # No next permutation for identity permutation

    j = n
    while perm[i - 1] >= perm[j] and j > i:
        j -= 1

    perm[i - 1], perm[j] = perm[j], perm[i - 1]

    start = i + 1
    end = n - 1
    while start < end:
        temp = perm[start]
        perm[start] = perm[end]
        perm[end] = temp
        start += 1
        end -= 1

def is_valid(perm, fixedness):
    if fixedness == 0 or fixedness == len(perm) or any([perm[i] != i for i in range(len(perm))]):
        return False
    temp = [0] * len(perm)
    for i in range(len(perm)):
        temp[perm[i]] += 1

    res = 0
    for j in range(len(perm)):
        res += min(temp[j], fixedness)

    return res == fixedness

