import heapq

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]
    visited = set()

    while priority_queue:
        (dist, current) = heapq.heappop(priority_queue)
        if current in visited:
            continue
        visited.add(current)

        for neighbor, weight in graph[current].items():
            distance = dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def floyd_warshall(Graph):
    n = len(Graph)
    inf = float('inf')

    # Initialize the distance matrix as all infinity except for diagonal elements which are set to 0.
    dist = [[0 if i == j else inf for i in range(n)] for j in range(n)]

    for i in range(n):
        dist[i][i] = 0

    # Iterate through the vertices of the graph "k" times.
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if (Graph[i][k] < inf and Graph[k][j] < inf):
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    return dist

def solve():
    t = int(input().strip())
    for _ in range(t):
        n, m = map(int, input().split())

        # Build the graph where each cell with coordinates (i, j) is connected to 4 neighboring cells.
        graph = {(i, j): {} for i in range(1, n + 1) for j in range(1, m + 1)}
        for i in range(1, n):
            for j in range(1, m):
                graph[(i,j)][(i+1, j)] = 1   # Right
                graph[(i,j)][(i-1, j)] = 1   # Left
                graph[(i,j)][(i, j+1)] = 1   # Down
                graph[(i,j)][(i, j-1)] = 1   # Up

        # Add the portal in each cell, including start and end cells.
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                graph[(i,j)][(i,j)] = -1   # Portal

                if i == 1:   # Upper-left cell (Stanley's starting point)
                    graph[(i,j)][(i+1,j)] = -1

                if j == m:   # Lower-right cell (Stanley's destination)
                    graph[(i,j)][(i,j-1)] = -1

                if i == n:   # Upper-right cell (Megan's destination)
                    graph[(i,j)][(i,j+1)] = -1

                if j == 1:   # Lower-left cell (Megan's starting point)
                    graph[(i,j)][(i,j+1)] = -1

        # Distance to Stanley's destination and Megan's destination.
        stanley_destination_dist = dijkstra(graph, (1, 1))[(n, m)]
        megan_destination_dist = dijkstra(graph, (n, m))[(1, m)]

        # Floyd-Warshall algorithm to get the shortest path from the starting point to all other points.
        shortest_paths = floyd_warshall([[0 if i == j else stanley_destination_dist + k if i != n and j != m else megan_destination_dist + k for k in range(stanley_destination_dist, megan_destination_dist + 1)] for i in range(n) for j in range(m)])
        print(min([shortest_paths[1][j] for j in range(1, m)]))

