import sys
  from heapq import heappush, heappop

  def generate_edges(n, m):
      adjacencies = [[] for _ in range(n * m)]

      for i in range(1, n * m + 1):
          row, col = (i - 1) // m, (i - 1) % m
          if col < m - 1:
              heappush(adjacencies[i], (abs(col + 1 - col), i, i + 1))
          if row < n - 1:
              heappush(adjacencies[i], (abs(row + 1 - row), i, i + m))

      return adjacencies

  def dijkstra(edges):
      heap = [(cost, node) for _, nodes, _ in edges]
      distances = {node: float('inf') for _, nodes, _ in edges}
      dist_and_prev = {node: (float('inf'), None) for _, nodes, _ in edges}

      while heap:
          _, current = heappop(heap)
          if current < 0 or distances[current] == current:
              continue

          distances[current] = current
          dist_and_prev[current] = (current, None)

          for cost, next, edge in nodes:
              total = costs[edge]
              if total + current < 0 or distances[next] <= total + current:
                  continue

              distances[next] = min(distances[next], total + current)
              dist_and_prev[next] = (total + current, current)

      return distances

